html:
{% macro fmt(v) %}{{ '{:,.0f}'.format(v or 0).replace(',', ' ') }}{% endmacro %}
<style>
  .fk-page { font-family: Arial, sans-serif; color:#1a1a1a; padding:0; max-width: 760px; margin: 0 auto; }
  .fk-header { display: flex; align-items: center; justify-content: space-between; padding-bottom: 8px; border-bottom: 3px solid #0E5C8A; }
  .fk-logo img { height: 70px; }
  .fk-h-center { text-align: center; flex: 1; }
  .fk-h-center h1 { color:#0E5C8A; font-size: 22px; margin: 0; letter-spacing: 3px; font-weight: 800; }
  .fk-h-center .slogan { color:#F77F00; font-size: 11px; font-style: italic; margin: 2px 0 0; }
  .fk-h-right { text-align: right; font-size: 10px; color:#0E5C8A; font-weight: 600; }
  .fk-h-right .fk-num { background: #0E5C8A; color:white; padding: 4px 10px; font-weight: 700; font-size: 11px; border-radius: 4px; }
  .fk-h-right .fk-date { color:#666; margin-top: 4px; font-size: 10px; }
  .fk-objet { background: linear-gradient(135deg, #0E5C8A, #1976D2); color:white; padding: 10px 14px; margin: 14px 0; border-radius: 6px; }
  .fk-objet .lbl { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; opacity: 0.85; font-weight: 600; }
  .fk-objet .val { font-size: 13px; font-weight: 700; margin-top: 2px; }
  .fk-block { border: 1px solid #d0d7de; padding: 10px 12px; border-radius: 6px; background:#fafbfc; margin: 12px 0; }
  .fk-block h4 { margin: 0 0 6px; color:#0E5C8A; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; border-bottom: 1px solid #d0d7de; padding-bottom: 4px; }
  .fk-block p { margin: 2px 0; font-size: 11px; display:inline-block; margin-right:22px; }
  .fk-block strong { color:#0E5C8A; }
  table.fk-items { width: 100%; border-collapse: collapse; margin-top: 14px; font-size: 11px; }
  table.fk-items thead th { background: linear-gradient(135deg, #0E5C8A, #1976D2); color:white; padding: 8px 10px; text-transform: uppercase; font-size: 10px; letter-spacing: 1px; text-align: left; }
  table.fk-items thead th.right { text-align: right; }
  table.fk-items thead th.center { text-align: center; }
  table.fk-items tbody td { padding: 8px 10px; border-bottom: 1px solid #e2e8f0; }
  table.fk-items tbody tr:nth-child(even) { background: #f8fafd; }
  table.fk-items tbody td.right { text-align: right; }
  table.fk-items tbody td.center { text-align: center; }
  .fk-totaux { margin-top: 14px; display: flex; justify-content: flex-end; }
  .fk-totaux table { font-size: 11px; min-width: 340px; }
  .fk-totaux td { padding: 5px 10px; }
  .fk-totaux .lbl { color:#666; }
  .fk-totaux .val { text-align: right; font-weight: 600; }
  .fk-totaux .total-final td { background: #0E5C8A; color:white; font-size: 13px; font-weight: 800; padding: 8px 12px; }
  .fk-lettres { margin-top: 14px; border-left: 4px solid #F77F00; padding: 8px 14px; background: #fff7ed; font-size: 11px; font-style: italic; }
  .fk-etab { margin-top: 24px; border-top: 2px solid #0E5C8A; padding-top: 14px; display: flex; justify-content: flex-end; }
  .fk-sig-box { width: 45%; text-align:center; }
  .fk-sig-box h4 { margin:0 0 6px; color:#0E5C8A; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; }
  .fk-sig-area { border: 1px dashed #cbd5e1; min-height: 70px; padding: 6px; background: #fafbfc; border-radius: 4px; }
  .fk-sig-area img { max-height: 60px; }
  .fk-footer { margin-top: 22px; border-top: 1px solid #d0d7de; padding-top: 8px; text-align: center; font-size: 9px; color:#666; }
  .fk-footer .slog { color:#F77F00; font-weight: 700; font-style: italic; }
</style>

<div class="fk-page">
  <div class="fk-header">
    <div class="fk-logo">
      <img src="/assets/kya_hr/images/logo_kya.png" onerror="this.src='/files/vrai.png'">
    </div>
    <div class="fk-h-center">
      <h1>FACTURE</h1>
      <p class="slogan">KYA, move beyond the sky!</p>
    </div>
    <div class="fk-h-right">
      <div class="fk-num">Facture N&deg;{{ doc.numero_facture }}</div>
      <div class="fk-date">{{ doc.lieu or 'Lome' }}, le {{ frappe.utils.formatdate(doc.date_facture, 'dd MMMM yyyy') }}</div>
    </div>
  </div>

  <div class="fk-objet">
    <div class="lbl">Objet</div>
    <div class="val">{{ doc.objet }}</div>
  </div>

  <div class="fk-block">
    <h4>Client</h4>
    <p><strong>Nom :</strong> {{ doc.client_nom or '' }}</p>
    {% if doc.client_adresse %}<p><strong>Adresse :</strong> {{ doc.client_adresse }}</p>{% endif %}
    <p><strong>Ville :</strong> {{ doc.client_ville or 'Lome' }}</p>
    {% if doc.client_telephone %}<p><strong>Telephone :</strong> {{ doc.client_telephone }}</p>{% endif %}
    {% if doc.client_email %}<p><strong>Email :</strong> {{ doc.client_email }}</p>{% endif %}
  </div>

  <table class="fk-items">
    <thead>
      <tr>
        <th class="center" style="width:6%">N&deg;</th>
        <th style="width:40%">DESIGNATION</th>
        <th class="center" style="width:8%">Unite</th>
        <th class="center" style="width:10%">Qte</th>
        <th class="right" style="width:16%">PU HT/HD</th>
        <th class="right" style="width:20%">Prix Total HT/HD</th>
      </tr>
    </thead>
    <tbody>
      {% for it in doc.articles %}
      <tr>
        <td class="center">{{ loop.index }}</td>
        <td>{{ it.description }}</td>
        <td class="center">{{ it.unite or '' }}</td>
        <td class="center">{{ '{:g}'.format(it.quantite or 0) }}</td>
        <td class="right">{{ fmt(it.prix_unitaire) }}</td>
        <td class="right">{{ fmt(it.total) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="fk-totaux">
    <table>
      <tr><td class="lbl">TOTAL HT BRUT</td><td class="val">{{ fmt(doc.total_ht_brut) }} XOF</td></tr>
      {% if doc.remise_montant %}<tr><td class="lbl">REMISE ({{ '{:g}'.format(doc.remise_taux or 0) }}%)</td><td class="val">- {{ fmt(doc.remise_montant) }} XOF</td></tr>
      <tr><td class="lbl">TOTAL APRES REMISE</td><td class="val">{{ fmt(doc.total_apres_remise) }} XOF</td></tr>{% endif %}
      <tr><td class="lbl">TVA ({{ '{:g}'.format(doc.tva_taux or 0) }}%)</td><td class="val">{{ fmt(doc.tva_montant) }} XOF</td></tr>
      <tr class="total-final"><td>TOTAL TTC (CFA)</td><td style="text-align:right">{{ fmt(doc.total_ttc) }}</td></tr>
    </table>
  </div>

  <div class="fk-lettres">
    Arretee la presente facture a la somme de {{ doc.montant_en_lettres or (frappe.utils.money_in_words(doc.total_ttc, 'XOF')) }}.
  </div>

  <div class="fk-etab">
    <div class="fk-sig-box">
      <h4>{{ doc.etabli_par_fonction or 'Directeur General' }}</h4>
      <div class="fk-sig-area">{% if doc.signature %}<img src="{{ doc.signature }}">{% endif %}</div>
      <p style="margin-top:6px; font-size:11px;"><strong>{{ doc.etabli_par_nom or '' }}</strong></p>
    </div>
  </div>

  <div class="fk-footer">
    <p class="slog">KYA, move beyond the sky!</p>
    <p>08 BP 81101 Agoe-Logope, Lome-TOGO &nbsp;&middot;&nbsp; www.kya-energy.com &nbsp;&middot;&nbsp; info@kya-energy.com</p>
    <p>N&deg; RCCM: TG-LOM 2015 B 975 &nbsp;&middot;&nbsp; NIF: 1000430317 &nbsp;&middot;&nbsp; CNSS: 48863</p>
  </div>
</div>
